class Record:
    def __init__(self, record_id, parent_id):
        self.record_id = record_id
        self.parent_id = parent_id


class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.children = []


def BuildTree(records):
    # Empty input -> no tree
    if not records:
        return None

    # Work on a copy to avoid mutating caller's list
    records_sorted = sorted(records, key=lambda r: r.record_id)
    ids = [r.record_id for r in records_sorted]
    n = len(ids)

    # IDs must start at 0
    if ids[0] != 0:
        raise ValueError("Root record must have id 0")

    # IDs must be continuous 0..n-1 and unique
    if ids != list(range(n)):
        raise ValueError("Record ids must be continuous and start at 0")

    # Prepare nodes
    nodes = [Node(i) for i in range(n)]

    # Validate parent relationships and build tree
    for r in records:
        rid = r.record_id
        pid = r.parent_id

        # parent id must be within bounds
        if pid < 0 or pid >= n:
            raise ValueError(f"Record {rid} has invalid parent id {pid}")

        # root record rules
        if rid == 0:
            if pid != 0:
                raise ValueError(f"Root record has parent id {pid}")
            # root is fine, do not attach to any parent
            continue

        # for non-root, parent must be strictly less than record id
        if pid >= rid:
            raise ValueError(f"Record {rid} has parent id {pid} which is not less than its id")

    # After validation attach children (preserve input order of records)
    for r in records:
        if r.record_id == 0:
            continue
        parent = nodes[r.parent_id]
        child = nodes[r.record_id]
        parent.children.append(child)

    return nodes[0]
